export const hashModule = {
  hashPassword: async (password: string): Promise<string> =>
    `scrypt$${password.length}$${simpleHash(password)}`,
  verifyPassword: async (password: string, hash: string): Promise<boolean> =>
    (await hashModule.hashPassword(password)) === hash,
  hashToken: (token: string): string => `sha256$${simpleHash(token)}`,
  randomToken: (bytes = 32): string =>
    `t${simpleHash(String(tokenCounter++))}`.padEnd(bytes, "x"),
};

let tokenCounter = 1;

/* -------------------------------------------------------- @/lib/rate-limit */

/** Verdicts the suite can steer: the default is "always allowed". */
export const rateLimitState = { allowed: true, remaining: 100 };

export const rateLimitModule = {
  consumeRateLimit: async (
    _orgId: OrgId,
    _bucketKey: string,
    cost = 1,
  ): Promise<{
    allowed: boolean;
    remaining: number;
    resetAt: IsoTimestamp;
  }> => ({
    allowed: rateLimitState.allowed,
    remaining: Math.max(0, rateLimitState.remaining - cost),
    resetAt: new Date(Date.now() + 60_000).toISOString() as IsoTimestamp,
  }),
  getBucketConfig: () => ({ capacity: 100, refillPerMinute: 100 }),
  RATE_LIMIT_BUCKETS: {} as Readonly<
    Record<string, { capacity: number; refillPerMinute: number }>
  >,
};

/* ---------------------------------------------------------- @/lib/mentions */

export const mentionsModule = {
  extractMentions: (body: string): readonly string[] =>
    [...body.matchAll(/@([\w.-]+)/g)].map((match) => match[1] ?? ""),
  resolveMentions: (
    body: string,
    members: readonly MemberWithUser[],
  ): readonly UserId[] => {
    const handles = new Set(
      mentionsModule.extractMentions(body).map((handle) => handle.toLowerCase()),
    );
    return members
      .filter(
        (member) =>
          handles.has(member.user.name.toLowerCase()) ||
          handles.has(member.user.email.split("@")[0]?.toLowerCase() ?? ""),
      )
      .map((member) => member.userId);
  },
  highlightMentions: (body: string): string =>
    body.replace(/@([\w.-]+)/g, "<b>@$1</b>"),
};

/* ------------------------------------------------------------ @/lib/logger */

export const loggerModule = {
  createLogger: () => ({
    debug: () => undefined,
    info: () => undefined,
    warn: () => undefined,
    error: () => undefined,
  }),
};

/* --------------------------------------------------------------- @/lib/csv */

export const csvModule = {
  toCsv: (
    rows: readonly Readonly<
      Record<string, string | number | boolean | null>
    >[],
    columns: readonly string[],
  ): string =>
    [
      columns.join(","),
      ...rows.map((row) =>
        columns.map((column) => csvModule.escapeCsvValue(row[column] ?? null)).join(","),
      ),
    ].join("\n"),
  escapeCsvValue: (value: string | number | boolean | null): string => {
    const text = value === null ? "" : String(value);
    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
  },
  csvResponseHeaders: (filename: string) => ({
    "content-type": "text/csv",
    "content-disposition": `attachment; filename="${filename}"`,
  }),
};

function simpleHash(value: string): string {
  let hash = 2_166_136_261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash).toString(36);
}
/**
 * Streams the audit-log CSV; requires `activity:export`.
 *
 * Owner D. `activity:export` sits above `activity:read` in `ROLE_MATRIX` —
 * reading the feed in the UI and walking off with the whole audit trail are
 * different privileges.
 *
 * Must call (do not reimplement): can, isEnabled, toCsv
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { csvResponseHeaders, toCsv } from "@/lib/csv";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { exportActivitySchema } from "@/schemas/activity";
import { listActivity } from "@/server/services/activity-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActivityEvent } from "@/types/activity";

export const dynamic = "force-dynamic";

const EXPORT_PAGE_LIMIT = 100;

const COLUMNS: readonly string[] = [
  "occurredAt",
  "action",
  "actorId",
  "subjectKind",
  "subjectId",
  "projectId",
  "summary",
];

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    const actor = await getActor(orgSlug);
    const { organization } = await getOrganizationSummary(actor, actor.orgId);

    if (!can(actor, "activity:export", { kind: "activity", orgId: actor.orgId })) {
      return failure("forbidden", "Exporting the audit log requires an admin.");
    }

    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
      return failure("forbidden", "CSV export is not included in this plan.");
    }

    const parsed = exportActivitySchema.safeParse({
      orgId: actor.orgId,
      since: url.searchParams.get("since"),
      until: url.searchParams.get("until"),
      format: url.searchParams.get("format") ?? "csv",
    });
    if (!parsed.success) {
      return failure(
        "validation_failed",
        "since and until must be ISO-8601 timestamps.",
      );
    }

    const page = await listActivity(actor, {
      orgId: parsed.data.orgId,
      since: parsed.data.since,
      until: parsed.data.until,
      limit: EXPORT_PAGE_LIMIT,
    });

    if (parsed.data.format === "json") {
      return Response.json({ items: page.items, total: page.total });
    }

    const csv = toCsv(page.items.map(toRow), COLUMNS);
    return new Response(csv, {
      headers: csvResponseHeaders(`taskflow-activity-${organization.slug}.csv`),
    });
  } catch (error) {
    return errorResponse(error);
  }
}

