      await emit("issue.status_changed", {
        orgId: other.org.id, actorId: other.userIds.member,
        occurredAt: new Date(base + Math.floor(i / 3) * 1000).toISOString() as never,
        issueId: `I${i}` as never, projectId: other.project.id, from: "backlog", to: "todo",
      });
    }
    const json = JSON.parse(await activityService.exportActivity(other.actors.admin, {
      orgId: other.org.id, since: "2025-01-01T00:00:00Z" as never, until: "2025-01-01T00:06:40Z" as never, format: "json",
    }));
    expect(json).toHaveLength(1203);
    expect(new Set(json.map((e: { id: string }) => e.id)).size).toBe(1203);
    expect(json[0].metadata).toEqual({ from: "backlog", to: "todo" });
    for (let i = 1; i < json.length; i += 1) expect(json[i - 1].occurredAt >= json[i].occurredAt).toBe(true);

    const instant = JSON.parse(await activityService.exportActivity(other.actors.admin, {
      orgId: other.org.id, since: "2025-01-01T00:00:10.000Z" as never, until: "2025-01-01T00:00:10Z" as never, format: "json",
    }));
    expect(instant).toHaveLength(3);

    await expect(activityService.exportActivity(other.actors.admin, {
      orgId: other.org.id, since: "2025-01-02T00:00:00.000Z" as never, until: "2025-01-01T00:00:00.000Z" as never, format: "json",
    })).rejects.toThrow();
    await expect(activityService.listActivity(other.actors.admin, {
      orgId: other.org.id, since: "2025-01-02T00:00:00.000Z" as never, until: "2025-01-01T00:00:00.000Z" as never, limit: 10, cursor: null,
    })).rejects.toThrow();

    const csv = await activityService.exportActivity(other.actors.admin, {
      orgId: other.org.id, since: "2025-01-01T00:00:00Z" as never, until: "2025-01-01T00:06:40Z" as never, format: "csv",
    });
    expect(csv.split("\r\n")).toHaveLength(1204);

    // paged feed walk
    const seen: string[] = [];
    let cursor: string | null = null;
    do {
      const page = await activityService.listActivity(other.actors.member, { orgId: other.org.id, limit: 100, cursor });
      seen.push(...page.items.map((e) => e.id));
      cursor = page.nextCursor;
    } while (cursor);
    expect(new Set(seen).size).toBe(1203);
    expect(seen).toEqual(json.map((e: { id: string }) => e.id));
  });
});
