    await commentService.deleteComment(A, { orgId: t.org.id, commentId: c.id });
    await issueService.archiveIssue(A, t.org.id, issue.id);
    await projectService.archiveProject(A, { orgId: t.org.id, projectId: p.id, archiveIssues: true });
