    await flagService.toggleFlag(t.actors.owner, { orgId: t.org.id, flag: "csv_export", enabled: true } as never).catch((e) => console.log("flag", e.message));
    await orgService.updateOrganization(t.actors.owner, { orgId: t.org.id, name: "Renamed" } as never);

    const rows = await all();
    const counts: Record<string, number> = {};
    for (const r of rows) counts[r.action] = (counts[r.action] ?? 0) + 1;
    console.log(counts);
    console.log(rows.map((r) => `${r.action} actor=${r.actorId} proj=${r.projectId} ${r.summary} ${JSON.stringify(r.metadata)}`).join("\n"));
    for (const [k, v] of Object.entries(counts)) expect([k, v]).toEqual([k, 1]);

    const feed = await activityService.listActivity(t.actors.member, { orgId: t.org.id, projectId: p.id, limit: 100, cursor: null });
    console.log(feed.items.map((r) => r.action));
    const assigned = rows.find((r) => r.action === "issue.assigned")!;
    expect(assigned.actorId).toBe(t.userIds.admin);
